const ts = require("typescript");
function check(code, useAjv6) {
  const config = ts.readConfigFile("tsconfig.json", ts.sys.readFile).config;
  const parsed = ts.parseJsonConfigFileContent(config, ts.sys, process.cwd());
  if (useAjv6) parsed.options.paths = { ajv: ["./node_modules/eslint/node_modules/ajv/lib/ajv.d.ts"] };
  const host = ts.createCompilerHost(parsed.options);
  const origGetSourceFile = host.getSourceFile.bind(host);
  host.getSourceFile = (fileName, languageVersion, onError, shouldCreateNewSourceFile) => {
    if (fileName.endsWith("src/orchestration/tools/registry.ts")) {
      return ts.createSourceFile(fileName, code, languageVersion);
    }
    return origGetSourceFile(fileName, languageVersion, onError, shouldCreateNewSourceFile);
  };
  const prog = ts.createProgram(["src/orchestration/tools/registry.ts"], parsed.options, host);
  const diags = ts.getPreEmitDiagnostics(prog);
  console.log(useAjv6 ? "AJV6" : "AJV8", "diags:", diags.map(d => ts.flattenDiagnosticMessageText(d.messageText, "\n")));
}
const sample = `
import Ajv from "ajv";
import type {ErrorObject, ValidateFunction} from "ajv";
const Ctor = (typeof Ajv === "function" ? Ajv : (Ajv as {default: new (opts: Record<string, unknown>) => {compile: (s: Record<string, unknown>) => ValidateFunction}}).default) as new (opts: Record<string, unknown>) => {compile: (s: Record<string, unknown>) => ValidateFunction};
const ajv = new Ctor({allErrors: true, strict: false, validateFormats: false, format: false, jsonPointers: true, logger: false});
const v: ValidateFunction = ajv.compile({});
const errs: ErrorObject[] = v.errors ?? [];
const e = errs[0] as {instancePath?: string; dataPath?: string} | undefined;
console.log(e?.instancePath ?? e?.dataPath);
`;
check(sample, false);
check(sample, true);
'

