(async () => {
  const ts = require("typescript");
  const files = [
    "src/orchestration/tools/registry.ts",
    "src/orchestration/tools/registry.test.ts",
    "src/orchestration/tools/registry.acceptance.test.ts",
    "src/orchestration/chatOrchestrator.test.ts",
    "example/weather-tool.ts"
  ];
  for (const useAjv6 of [false, true]) {
    const config = ts.readConfigFile("tsconfig.json", ts.sys.readFile).config;
    const parsed = ts.parseJsonConfigFileContent(config, ts.sys, process.cwd());
    if (useAjv6) parsed.options.paths = { ajv: ["./node_modules/eslint/node_modules/ajv/lib/ajv.d.ts"] };
    const prog = ts.createProgram(files, parsed.options);
    const diags = ts.getPreEmitDiagnostics(prog);
    console.log(useAjv6 ? "TS(ajv6)" : "TS(ajv8)", "errors:", diags.length);
    for (const d of diags) {
      console.log(d.file?.fileName, ts.flattenDiagnosticMessageText(d.messageText, "\n"));
    }
  }
  const {ESLint} = await import("eslint");
  const eslint = new ESLint();
  const lintResults = await eslint.lintFiles([
    ...files,
    "specs/hal-engine-tool-input-validation/spec.md",
    "adrs/ADR-002-response-validation.md",
    "docs/adding-a-tool.md",
    "README.md",
    ".specify/spec.md",
    "CHANGELOG.md"
  ]);
  let lintErrors = 0;
  for (const r of lintResults) {
    for (const m of r.messages) {
      lintErrors += 1;
      console.log(`ESLINT ${r.filePath}:${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
    }
  }
  console.log("ESLINT total issues:", lintErrors, "RSS MB:", Math.round(process.memoryUsage().rss / 1024 / 1024));
  if (lintErrors > 0) process.exit(1);
})();
'

